import { useState, useEffect } from 'react';

interface PerformanceMetric {
  id: number;
  name: string;
  value: number;
  target: number;
  unit: string;
  trend: 'up' | 'down' | 'stable';
}

interface PerformanceViewProps {
  restaurantId: number | null;
}

export default function PerformanceView({ restaurantId }: PerformanceViewProps) {
  const [metrics, setMetrics] = useState<PerformanceMetric[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  
  // Fetch performance metrics for the selected restaurant
  useEffect(() => {
    const fetchPerformanceData = async () => {
      if (!restaurantId) {
        setMetrics([]);
        return;
      }
      
      setLoading(true);
      setError(null);
      
      try {
        // This would be replaced with an actual API call
        // const response = await fetch(`http://localhost:3001/performance/${restaurantId}`);
        
        // For now, we'll use mock data
        const mockData: PerformanceMetric[] = [
          {
            id: 1,
            name: 'Food Cost Percentage',
            value: 28.5,
            target: 30,
            unit: '%',
            trend: 'down'
          },
          {
            id: 2,
            name: 'Labor Cost Percentage',
            value: 32.1,
            target: 30,
            unit: '%',
            trend: 'up'
          },
          {
            id: 3,
            name: 'Average Prep Time',
            value: 45,
            target: 40,
            unit: 'minutes',
            trend: 'stable'
          },
          {
            id: 4,
            name: 'Inventory Turnover',
            value: 12,
            target: 15,
            unit: 'turns/month',
            trend: 'up'
          },
          {
            id: 5,
            name: 'Waste Percentage',
            value: 3.2,
            target: 3,
            unit: '%',
            trend: 'down'
          }
        ];
        
        // Simulate API delay
        setTimeout(() => {
          setMetrics(mockData);
          setLoading(false);
        }, 500);
      } catch (error) {
        console.error('Error fetching performance data:', error);
        setError(error instanceof Error ? error.message : 'Unknown error');
        setLoading(false);
      }
    };
    
    fetchPerformanceData();
  }, [restaurantId]);
  
  if (!restaurantId) {
    return <div>Please select a restaurant to view performance metrics.</div>;
  }
  
  if (loading) {
    return <div>Loading performance data...</div>;
  }
  
  if (error) {
    return <div className="text-red-500">Error: {error}</div>;
  }
  
  return (
    <div>
      <h2 className="text-xl font-bold mb-6">Performance Metrics</h2>
      
      {/* Performance Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
        {metrics.map(metric => (
          <div key={metric.id} className="bg-white rounded-lg shadow p-6">
            <div className="flex justify-between items-start">
              <h3 className="font-semibold text-lg">{metric.name}</h3>
              <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${
                metric.trend === 'up' && metric.value > metric.target ? 'bg-red-100 text-red-800' :
                metric.trend === 'up' && metric.value <= metric.target ? 'bg-green-100 text-green-800' :
                metric.trend === 'down' && metric.value < metric.target ? 'bg-green-100 text-green-800' :
                metric.trend === 'down' && metric.value >= metric.target ? 'bg-red-100 text-red-800' :
                'bg-gray-100 text-gray-800'
              }`}>
                {metric.trend === 'up' ? '↑' : metric.trend === 'down' ? '↓' : '→'} {metric.trend}
              </span>
            </div>
            
            <div className="mt-4">
              <div className="flex items-baseline">
                <span className="text-3xl font-bold">{metric.value}</span>
                <span className="ml-1 text-gray-500">{metric.unit}</span>
              </div>
              <div className="text-sm text-gray-500 mt-1">
                Target: {metric.target} {metric.unit}
              </div>
            </div>
            
            {/* Progress Bar */}
            <div className="mt-4">
              <div className="w-full bg-gray-200 rounded-full h-2.5 mb-1">
                <div 
                  className={`h-2.5 rounded-full ${
                    metric.value >= metric.target ? 'bg-green-500' : 'bg-orange-500'
                  }`}
                  style={{ 
                    width: `${Math.min(100, (metric.value / metric.target) * 100)}%` 
                  }}
                ></div>
              </div>
              <div className="flex justify-between text-xs text-gray-500">
                <span>0</span>
                <span>{metric.target * 2} {metric.unit}</span>
              </div>
            </div>
          </div>
        ))}
      </div>
      
      {/* Note about mock data */}
      <div className="bg-blue-50 p-4 rounded-lg">
        <p className="text-sm text-blue-800">
          Note: This is currently displaying mock data. Connect to your actual performance metrics API to see real data.
        </p>
      </div>
    </div>
  );
} 